import { Route } from "../route/client.js";
import { Endpoint } from "../route/endpoint.js";
import { AnthropicMessages } from "../protocols/anthropic-messages.js";
import { OpenAIChat } from "../protocols/openai-chat.js";
import { OpenResponses } from "../protocols/open-responses.js";
import { BedrockAuth } from "../protocols/utils/bedrock-auth.js";
import { claudeVersion } from "../protocols/utils/claude-model.js";
import { ProviderConfigurationError, ProviderID } from "../schema/index.js";
import { withOpenAIOptions } from "./openai-options.js";
export const id = ProviderID.make("amazon-bedrock");
const responsesRoute = Route.make({
    id: "bedrock-mantle-responses",
    provider: id,
    providerMetadataKey: "mantle",
    protocol: OpenResponses.protocol,
    endpoint: Endpoint.path(OpenResponses.PATH),
    transport: OpenResponses.httpTransport,
    defaults: { providerOptions: { store: false, include: ["reasoning.encrypted_content"] } },
});
const chatRoute = OpenAIChat.route.with({
    id: "bedrock-mantle-chat",
    provider: id,
    providerMetadataKey: "mantle",
});
const messagesRoute = Route.make({
    id: "bedrock-mantle-messages",
    provider: id,
    providerMetadataKey: "mantle",
    protocol: {
        ...AnthropicMessages.protocol,
        // Mantle rejects mid-conversation `output_config` on Opus 5.0; support starts at 5.1+.
        supportsEffortUpdates: (request) => {
            if (!(AnthropicMessages.protocol.supportsEffortUpdates?.(request) ?? false))
                return false;
            if (request.model.compatibility?.supportsEffortUpdates !== undefined)
                return true;
            const version = claudeVersion(request.model.id);
            return version !== undefined && (version.major > 5 || (version.major === 5 && version.minor >= 1));
        },
    },
    endpoint: Endpoint.path(AnthropicMessages.PATH),
    transport: AnthropicMessages.transport(),
    headers: () => ({ "anthropic-version": "2023-06-01" }),
});
export const routes = [responsesRoute, chatRoute, messagesRoute];
const configuredRoute = (route, input, defaultBaseURL = (region) => `https://bedrock-mantle.${region}.api.aws/v1`) => {
    const region = BedrockAuth.resolveRegion(input);
    return route.with({
        endpoint: { baseURL: input.baseURL ?? defaultBaseURL(region) },
        auth: BedrockAuth.resolveAuth(input, region, {
            service: "bedrock-mantle",
            name: "Bedrock Mantle",
            mode: input.auth,
        }),
    });
};
const defaults = (input) => {
    const { apiKey: _, auth: _auth, baseURL: _baseURL, credentials: _credentials, profile: _profile, region: _region, ...rest } = input;
    return rest;
};
export const configure = (input = {}) => {
    if (input.auth === "bearer" && input.apiKey === undefined && process.env.AWS_BEARER_TOKEN_BEDROCK === undefined)
        throw new ProviderConfigurationError({ provider: id, message: "Amazon Bedrock Mantle bearer auth requires apiKey" });
    if (input.auth === "sigv4" && input.apiKey !== undefined)
        throw new ProviderConfigurationError({
            provider: id,
            message: "Amazon Bedrock Mantle SigV4 auth does not accept apiKey",
        });
    const configuredResponsesRoute = configuredRoute(responsesRoute, input);
    const configuredChatRoute = configuredRoute(chatRoute, input);
    const configuredMessagesRoute = configuredRoute(messagesRoute, input, (region) => `https://bedrock-mantle.${region}.api.aws/anthropic/v1`);
    const modelDefaults = defaults(input);
    const responses = (modelID) => configuredResponsesRoute
        .with(withOpenAIOptions(modelID, modelDefaults))
        .model({ id: modelID });
    const chat = (modelID) => configuredChatRoute
        .with(withOpenAIOptions(modelID, modelDefaults))
        .model({ id: modelID });
    const messages = (modelID) => configuredMessagesRoute.with(modelDefaults).model({ id: modelID });
    return {
        id,
        model: responses,
        chat,
        messages,
        responses,
        configure,
    };
};
export const provider = configure();
const fromSettings = ({ apiKey, auth, baseURL, body, credentials, headers, profile, region, topP, ...providerOptions }) => configure({
    apiKey,
    auth,
    baseURL,
    credentials,
    generation: topP === undefined ? undefined : { topP },
    headers,
    http: body === undefined ? undefined : { body },
    profile,
    providerOptions,
    region,
});
export const chatModel = (modelID, settings) => fromSettings(settings).chat(modelID);
export const messagesModel = (modelID, settings) => fromSettings(settings).messages(modelID);
export const responsesModel = (modelID, settings) => fromSettings(settings).responses(modelID);
export const model = responsesModel;
